"use client";

import {useCallback, useEffect, useRef, useState, type CSSProperties, type FormEvent} from "react";
import {Archive, ArrowLeft, ArrowRight, ArrowUpRight, BarChart3, Check, ChevronDown, ChevronUp, Copy, Download, ExternalLink, Eye, Globe2, Heading, Image as ImageIcon, LayoutGrid, Link2, LoaderCircle, LockKeyhole, LogOut, Palette, Plus, RefreshCw, RotateCcw, Settings2, ShieldCheck, Sparkles, Upload, Users, X} from "lucide-react";
import type {AnalyticsData, AnalyticsRange, HubLink, HubPlan, HubProfile, HubTemplate, OperatorData, PageEditorData, PageSummary, WorkspaceData} from "../../lib/hub-types";
import {HubBrand, HubIcon} from "./ui";
import {HubCanvas} from "./HubCanvas";
import "../studio.css";

type Screen="pages"|"create"|"editor"|"account"|"operator";
type EditorTab="content"|"appearance"|"analytics";
type ApiError=Error&{status?:number;signInUrl?:string};
type LinkDraft=Pick<HubLink,"type"|"title"|"description"|"url"|"icon"|"enabled"|"featured">;
const count=new Intl.NumberFormat("th-TH");
const RANGES:{value:AnalyticsRange;label:string}[]=[{value:"today",label:"วันนี้"},{value:"7d",label:"7 วัน"},{value:"30d",label:"30 วัน"},{value:"all",label:"ทั้งหมด"}];
const TEMPLATES:{id:HubTemplate;name:string;description:string;layout:string;accent:string}[]=[{id:"creator",name:"ครีเอเตอร์",description:"ผลงาน เรื่องราว และช่องทางติดตาม",layout:"stack",accent:"#04878a"},{id:"business",name:"ธุรกิจและบริการ",description:"แนะนำแบรนด์ พร้อมช่องทางติดต่อ",layout:"editorial",accent:"#376248"},{id:"shop",name:"ร้านค้า",description:"จัดสินค้าและช่องทางสั่งซื้อเป็นหมวด",layout:"grid",accent:"#a66543"}];
const ICONS=[{id:"link",label:"ลิงก์"},{id:"globe",label:"เว็บไซต์"},{id:"line",label:"LINE"},{id:"instagram",label:"Instagram"},{id:"facebook",label:"Facebook"},{id:"youtube",label:"YouTube"},{id:"tiktok",label:"TikTok"},{id:"mail",label:"อีเมล"},{id:"map",label:"แผนที่"},{id:"shop",label:"ร้านค้า"},{id:"file",label:"เอกสาร"},{id:"briefcase",label:"งาน"}];
const BACKGROUNDS:{id:HubProfile["background"];name:string;color:string}[]=[{id:"mint",name:"Mint",color:"#e8f3ee"},{id:"sand",name:"Sand",color:"#f6eee2"},{id:"lavender",name:"Lavender",color:"#eeebf5"},{id:"ink",name:"Ink",color:"#223533"}];

async function api<T>(url:string,init?:RequestInit):Promise<T>{let response:Response;try{response=await fetch(url,{...init,cache:"no-store",headers:{...(init?.body&&!(init.body instanceof FormData)?{"Content-Type":"application/json"}:{}),...init?.headers}});}catch{throw new Error("เชื่อมต่อไม่สำเร็จ กรุณาตรวจสอบอินเทอร์เน็ตแล้วลองอีกครั้ง");}let body:any;try{body=await response.json();}catch{throw new Error("เซิร์ฟเวอร์ตอบกลับไม่สมบูรณ์ กรุณาลองใหม่");}if(!response.ok){const e:ApiError=new Error(typeof body.error==="string"?body.error:"ทำรายการไม่สำเร็จ กรุณาลองอีกครั้ง");e.status=response.status;e.signInUrl=body.signInUrl;throw e;}return body as T;}
function draftOf(link:HubLink):LinkDraft{return {type:link.type,title:link.title,description:link.description,url:link.url,icon:link.icon,enabled:link.enabled,featured:link.featured};}
function isUrl(value:string){try{const u=new URL(value);return ["https:","http:","mailto:"].includes(u.protocol)&&!u.username&&!u.password&&(u.protocol!=="mailto:"||!!u.pathname);}catch{return false;}}
function percent(n:number){return `${Number.isFinite(n)?Math.max(0,Math.min(100,n)).toFixed(n%1?1:0):0}%`;}
function dateLabel(n:number){return new Intl.DateTimeFormat("th-TH",{day:"numeric",month:"short",timeZone:"Asia/Bangkok"}).format(new Date(n));}
function pageStatus(page:PageSummary){return !page.published?"ฉบับร่าง":page.hasUnpublishedChanges?"มีการแก้ไขใหม่":"เผยแพร่แล้ว";}

export default function HubStudio(){
  const [workspace,setWorkspace]=useState<WorkspaceData|null>(null);
  const [loading,setLoading]=useState(true);
  const [loadError,setLoadError]=useState<ApiError|null>(null);
  const [screen,setScreen]=useState<Screen>("pages");
  const [editor,setEditor]=useState<PageEditorData|null>(null);
  const [editorTab,setEditorTab]=useState<EditorTab>("content");
  const [profile,setProfile]=useState<HubProfile|null>(null);
  const [slug,setSlug]=useState("");
  const [dirtyRows,setDirtyRows]=useState<Record<string,boolean>>({});
  const [busy,setBusy]=useState<string|null>(null);
  const [error,setError]=useState("");
  const [toast,setToast]=useState("");
  const [origin,setOrigin]=useState("");
  const [preview,setPreview]=useState(false);
  const [archivePage,setArchivePage]=useState<string|null>(null);
  const [unpublishConfirm,setUnpublishConfirm]=useState(false);
  const [operator,setOperator]=useState<OperatorData|null>(null);
  const [operatorLoading,setOperatorLoading]=useState(false);
  const [operatorError,setOperatorError]=useState("");
  const [name,setName]=useState("");
  const [newSlug,setNewSlug]=useState("");
  const [template,setTemplate]=useState<HubTemplate>("creator");
  const [newBlockType,setNewBlockType]=useState<"link"|"heading"|null>(null);
  const [newBlockTitle,setNewBlockTitle]=useState("");
  const [newBlockUrl,setNewBlockUrl]=useState("");
  const [slugCheck,setSlugCheck]=useState<{status:"idle"|"checking"|"available"|"taken"|"error";message:string}>({status:"idle",message:""});
  const toastTimer=useRef<ReturnType<typeof setTimeout>|null>(null);
  const uploadRef=useRef<HTMLInputElement>(null);
  const initialPageHandled=useRef(false);
  const profileDirtyRef=useRef(false);
  const previewOverlayRef=useRef<HTMLElement|null>(null);
  const previewCloseRef=useRef<HTMLButtonElement|null>(null);
  const notify=useCallback((message:string)=>{setToast(message);if(toastTimer.current)clearTimeout(toastTimer.current);toastTimer.current=setTimeout(()=>setToast(""),4000);},[]);
  const refreshWorkspace=useCallback(async()=>{const result=await api<WorkspaceData>("/api/workspace");setWorkspace(result);return result;},[]);
  const load=useCallback(async()=>{setLoading(true);setLoadError(null);try{await refreshWorkspace();}catch(e){setLoadError(e as ApiError);}finally{setLoading(false);}},[refreshWorkspace]);
  useEffect(()=>{setOrigin(window.location.origin);void load();return()=>{if(toastTimer.current)clearTimeout(toastTimer.current);};},[load]);
  useEffect(()=>{if(screen!=="create"||!newSlug){setSlugCheck({status:"idle",message:""});return;}if(!/^[a-z0-9][a-z0-9-]{1,38}[a-z0-9]$/.test(newSlug)||newSlug.includes("--")){setSlugCheck({status:"taken",message:"ใช้ตัวอักษรอังกฤษตัวเล็ก ตัวเลข หรือขีดกลาง 3–40 ตัว และไม่ใช้ขีดกลางติดกัน"});return;}let cancelled=false;setSlugCheck({status:"checking",message:"กำลังตรวจชื่อ URL"});const timer=setTimeout(()=>void api<{available:boolean;reason?:string}>(`/api/slugs?slug=${encodeURIComponent(newSlug)}`).then(result=>{if(!cancelled)setSlugCheck({status:result.available?"available":"taken",message:result.available?"ชื่อนี้ใช้ได้":result.reason||"ชื่อนี้ถูกใช้แล้ว ลองชื่ออื่นได้เลย"});}).catch(()=>{if(!cancelled)setSlugCheck({status:"error",message:"ตรวจชื่อไม่ได้ตอนนี้ ระบบจะตรวจอีกครั้งเมื่อสร้าง"});}),450);return()=>{cancelled=true;clearTimeout(timer);};},[newSlug,screen]);
  useEffect(()=>{if(screen!=="operator"||!workspace?.account.isOperator)return;let live=true;setOperatorLoading(true);setOperatorError("");void api<OperatorData>("/api/operator").then(result=>{if(live)setOperator(result);}).catch(e=>{if(live)setOperatorError((e as Error).message);}).finally(()=>{if(live)setOperatorLoading(false);});return()=>{live=false;};},[screen,workspace?.account.isOperator]);
  useEffect(()=>{window.scrollTo({top:0,left:0,behavior:"auto"});},[screen,editor?.page.id]);
  useEffect(()=>{
    if(!preview)return;
    const mobile=window.matchMedia("(max-width: 780px)");
    if(!mobile.matches){setPreview(false);return;}
    const previousFocus=document.activeElement instanceof HTMLElement?document.activeElement:null;
    const previousOverflow=document.body.style.overflow;
    document.body.style.overflow="hidden";
    previewCloseRef.current?.focus({preventScroll:true});
    function onKeyDown(event:KeyboardEvent){
      if(event.key==="Escape"){event.preventDefault();event.stopPropagation();setPreview(false);return;}
      if(event.key!=="Tab")return;
      const overlay=previewOverlayRef.current;
      if(!overlay)return;
      const focusable=Array.from(overlay.querySelectorAll<HTMLElement>('a[href],button:not([disabled]),input:not([disabled]),select:not([disabled]),textarea:not([disabled]),[tabindex]:not([tabindex="-1"])')).filter(element=>element.getClientRects().length>0&&!element.hasAttribute("hidden"));
      const first=focusable[0],last=focusable[focusable.length-1];
      if(!first){event.preventDefault();overlay.focus();return;}
      if(!overlay.contains(document.activeElement)||document.activeElement===overlay){event.preventDefault();(event.shiftKey?last:first).focus();return;}
      if(event.shiftKey&&document.activeElement===first){event.preventDefault();last.focus();}
      else if(!event.shiftKey&&document.activeElement===last){event.preventDefault();first.focus();}
    }
    const onWidthChange=()=>{if(!mobile.matches)setPreview(false);};
    document.addEventListener("keydown",onKeyDown,true);
    mobile.addEventListener("change",onWidthChange);
    return()=>{document.body.style.overflow=previousOverflow;document.removeEventListener("keydown",onKeyDown,true);mobile.removeEventListener("change",onWidthChange);if(previousFocus?.isConnected)previousFocus.focus({preventScroll:true});};
  },[preview]);
  const links=(editor?.links||[]).filter(link=>!link.archived).sort((a,b)=>a.sortOrder-b.sortOrder);
  const archivedLinks=(editor?.links||[]).filter(link=>link.archived);
  const unsavedRows=Object.values(dirtyRows).some(Boolean);
  const profileDirty=!!(editor&&profile&&(JSON.stringify(profile)!==JSON.stringify(editor.profile)||slug!==editor.page.slug));
  const hasUnsaved=unsavedRows||profileDirty||!!(newBlockType&&(newBlockTitle||newBlockUrl));
  profileDirtyRef.current=profileDirty;
  useEffect(()=>{if(!hasUnsaved)return;const guard=(event:BeforeUnloadEvent)=>{event.preventDefault();event.returnValue="";};window.addEventListener("beforeunload",guard);return()=>window.removeEventListener("beforeunload",guard);},[hasUnsaved]);
  useEffect(()=>{if(!workspace||initialPageHandled.current)return;initialPageHandled.current=true;const requested=new URLSearchParams(window.location.search).get("page");if(!requested)return;if(workspace.pages.some(page=>page.id===requested)){void openEditor(requested);}else{setError("ไม่พบฮับนี้ในบัญชีของคุณ หรือฮับถูกเก็บเข้าคลังแล้ว");}},[workspace]);
  const markDirty=useCallback((id:string,dirty:boolean)=>setDirtyRows(previous=>previous[id]===dirty?previous:{...previous,[id]:dirty}),[]);
  function adoptEditor(value:PageEditorData,preserveUnsaved=false){setEditor(value);if(!preserveUnsaved||!profileDirtyRef.current){setProfile(value.profile);setSlug(value.page.slug);}setUnpublishConfirm(false);}
  async function reloadEditor(){if(!editor)return;const result=await api<PageEditorData>(`/api/pages/${editor.page.id}`);adoptEditor(result,true);return result;}
  function navigate(next:Screen){if(screen==="editor"&&hasUnsaved){setError("มีข้อมูลที่ยังไม่ได้บันทึก กรุณาบันทึกหรือยกเลิกการแก้ไขก่อนเปลี่ยนหน้า");return;}setScreen(next);setError("");setArchivePage(null);setPreview(false);if(next!=="editor")window.history.replaceState(window.history.state,"","/studio");if(next==="pages")void refreshWorkspace().catch(e=>setError((e as Error).message));}
  function switchEditorTab(next:EditorTab){if(hasUnsaved){setError("มีข้อมูลที่ยังไม่ได้บันทึก กรุณาบันทึกหรือยกเลิกการแก้ไขก่อนเปลี่ยนแท็บ");return;}setEditorTab(next);setError("");setPreview(false);}
  async function openEditor(id:string){if(busy)return;setBusy("open-"+id);setError("");try{const value=await api<PageEditorData>(`/api/pages/${id}`);adoptEditor(value);setDirtyRows({});setNewBlockType(null);setEditorTab("content");setScreen("editor");window.history.replaceState(window.history.state,"",`/studio?page=${encodeURIComponent(id)}`);}catch(e){setError((e as Error).message);}finally{setBusy(null);}}
  function startCreate(){if(workspace&&workspace.usage.pages>=workspace.limits.maxPages){setScreen("account");setError("แพ็กเกจปัจจุบันใช้จำนวนฮับครบแล้ว ดูตัวเลือกแพ็กเกจได้ที่นี่");return;}setName("");setNewSlug("");setTemplate("creator");setScreen("create");setError("");}
  async function createPage(event:FormEvent){event.preventDefault();if(busy)return;setBusy("create");setError("");try{const value=await api<PageEditorData>("/api/pages",{method:"POST",body:JSON.stringify({name:name.trim(),slug:newSlug.trim(),template})});adoptEditor(value);setDirtyRows({});setNewBlockType(null);setEditorTab("content");setScreen("editor");window.history.replaceState(window.history.state,"",`/studio?page=${encodeURIComponent(value.page.id)}`);await refreshWorkspace();notify("สร้างฮับแล้ว เพิ่มลิงก์ของคุณได้เลย");}catch(e){setError((e as Error).message);}finally{setBusy(null);}}
  function addLink(type:"link"|"heading"){setNewBlockType(type);setNewBlockTitle("");setNewBlockUrl("");setError("");}
  async function createBlock(event:FormEvent){event.preventDefault();if(!editor||busy||!newBlockType)return;if(!newBlockTitle.trim()){setError("กรุณาใส่ชื่อรายการ");return;}if(newBlockType==="link"&&!isUrl(newBlockUrl.trim())){setError("ใส่ URL ปลายทางจริงที่เริ่มด้วย https://, http:// หรือ mailto:");return;}setBusy("add");setError("");try{await api<{link:HubLink}>(`/api/pages/${editor.page.id}/links`,{method:"POST",body:JSON.stringify({type:newBlockType,title:newBlockTitle.trim(),description:"",url:newBlockType==="heading"?"":newBlockUrl.trim(),icon:"link",enabled:true,featured:false})});await reloadEditor();setNewBlockType(null);setNewBlockTitle("");setNewBlockUrl("");await refreshWorkspace();notify("เพิ่มรายการในฉบับร่างแล้ว");}catch(e){setError((e as Error).message);}finally{setBusy(null);}}
  async function saveLink(link:HubLink,draft:LinkDraft):Promise<HubLink>{if(!editor||busy)throw new Error("กรุณารอให้รายการก่อนหน้าบันทึกเสร็จ");setBusy(link.id);setError("");try{const saved=await api<{link:HubLink}>(`/api/pages/${editor.page.id}/links/${link.id}`,{method:"PATCH",body:JSON.stringify(draft)});markDirty(link.id,false);await reloadEditor();notify("บันทึกลิงก์ในฉบับร่างแล้ว");return saved.link;}catch(e){setError((e as Error).message);throw e;}finally{setBusy(null);}}
  async function patchLink(link:HubLink,patch:Partial<HubLink>){if(!editor||busy)return;setBusy(link.id);setError("");try{await api(`/api/pages/${editor.page.id}/links/${link.id}`,{method:"PATCH",body:JSON.stringify(patch)});await reloadEditor();notify(patch.archived===false?"กู้คืนแล้ว ลิงก์ยังซ่อนอยู่จนกว่าจะเปิดใช้งาน":"บันทึกฉบับร่างแล้ว");}catch(e){setError((e as Error).message);}finally{setBusy(null);}}
  async function archiveLink(link:HubLink){if(!editor||busy)return;setBusy(link.id);setError("");try{await api(`/api/pages/${editor.page.id}/links/${link.id}`,{method:"DELETE"});markDirty(link.id,false);await reloadEditor();await refreshWorkspace();notify("เก็บเข้าคลังแล้ว ประวัติคลิกยังอยู่");}catch(e){setError((e as Error).message);}finally{setBusy(null);}}
  async function reorder(index:number,direction:number){if(!editor||busy)return;const ordered=[...links],target=index+direction;if(target<0||target>=ordered.length)return;[ordered[index],ordered[target]]=[ordered[target],ordered[index]];setBusy("reorder");setError("");try{await api(`/api/pages/${editor.page.id}/reorder`,{method:"POST",body:JSON.stringify({ids:ordered.map(link=>link.id)})});await reloadEditor();notify("บันทึกลำดับในฉบับร่างแล้ว");}catch(e){setError((e as Error).message);}finally{setBusy(null);}}
  async function saveProfile(event:FormEvent){event.preventDefault();if(!editor||!profile||busy)return;setBusy("profile");setError("");try{const result=await api<PageEditorData>(`/api/pages/${editor.page.id}`,{method:"PATCH",body:JSON.stringify({profile,...(slug!==editor.page.slug?{slug}:{})})});adoptEditor(result);await refreshWorkspace();notify("บันทึกหน้าตาในฉบับร่างแล้ว");}catch(e){setError((e as Error).message);}finally{setBusy(null);}}
  async function setAvatar(url:string){if(!editor)return;const result=await api<PageEditorData>(`/api/pages/${editor.page.id}`,{method:"PATCH",body:JSON.stringify({profile:{avatarUrl:url}})});setEditor(result);setProfile(previous=>previous?{...previous,avatarUrl:url}:result.profile);notify(url?"บันทึกรูปในฉบับร่างแล้ว":"นำรูปออกจากฉบับร่างแล้ว");}
  async function uploadAvatar(file?:File){if(!file||!editor||busy)return;if(!["image/png","image/jpeg","image/webp"].includes(file.type)||file.size>2*1024*1024){setError("เลือกรูป PNG, JPG หรือ WebP ขนาดไม่เกิน 2 MB");return;}setBusy("avatar");setError("");try{const form=new FormData();form.append("file",file);const result=await api<{url:string}>("/api/uploads",{method:"POST",body:form});await setAvatar(result.url);}catch(e){setError((e as Error).message);}finally{setBusy(null);if(uploadRef.current)uploadRef.current.value="";}}
  async function removeAvatar(){if(!editor||busy)return;setBusy("avatar");setError("");try{await setAvatar("");}catch(e){setError((e as Error).message);}finally{setBusy(null);}}
  async function publish(){if(!editor||busy||hasUnsaved)return;setBusy("publish");setError("");try{const result=await api<PageEditorData>(`/api/pages/${editor.page.id}/publish`,{method:"POST",body:JSON.stringify({revision:editor.revision})});adoptEditor(result);await refreshWorkspace();notify("เผยแพร่ฮับแล้ว ลิงก์ของคุณพร้อมใช้งาน");}catch(e){setError((e as Error).message);}finally{setBusy(null);}}
  async function unpublish(){if(!editor||busy)return;setBusy("unpublish");setError("");try{const result=await api<PageEditorData>(`/api/pages/${editor.page.id}/unpublish`,{method:"POST"});adoptEditor(result);await refreshWorkspace();notify("หยุดเผยแพร่ฮับแล้ว ข้อมูลยังอยู่ครบ");}catch(e){setError((e as Error).message);}finally{setBusy(null);}}
  async function deletePage(page:PageSummary){if(busy)return;setBusy(page.id);setError("");try{await api(`/api/pages/${page.id}`,{method:"DELETE"});await refreshWorkspace();setArchivePage(null);notify("เก็บฮับเข้าคลังแล้ว");}catch(e){setError((e as Error).message);}finally{setBusy(null);}}
  async function restorePage(page:PageSummary){if(busy)return;setBusy(page.id);setError("");try{await api<PageEditorData>(`/api/pages/${page.id}`,{method:"PATCH",body:JSON.stringify({archived:false})});await refreshWorkspace();notify("กู้คืนฮับแล้ว ตรวจสอบฉบับร่างก่อนเผยแพร่");}catch(e){setError((e as Error).message);}finally{setBusy(null);}}
  async function copyPage(page:PageSummary){try{await navigator.clipboard.writeText(`${window.location.origin}/h/${page.slug}`);notify("คัดลอกลิงก์ฮับแล้ว");}catch{setError("คัดลอกอัตโนมัติไม่ได้ เปิดฮับแล้วคัดลอกจากแถบที่อยู่ได้เลย");}}
  async function requestPro(){if(busy)return;setBusy("upgrade");setError("");try{await api("/api/account/upgrade",{method:"POST"});await refreshWorkspace();notify("ส่งคำขอ Pro แล้ว ผู้ดูแลจะตรวจสอบให้");}catch(e){setError((e as Error).message);}finally{setBusy(null);}}
  async function changePlan(id:string,plan:HubPlan){if(busy)return;setBusy(id);setOperatorError("");try{await api(`/api/operator/accounts/${id}`,{method:"PATCH",body:JSON.stringify({plan})});const result=await api<OperatorData>("/api/operator");setOperator(result);await refreshWorkspace();notify("อัปเดตแพ็กเกจแล้ว");}catch(e){setOperatorError((e as Error).message);}finally{setBusy(null);}}

  if(loading)return <div className="hs-auth"><HubBrand/><div className="hs-auth-card"><LoaderCircle className="hs-spin" size={29}/><h1>กำลังเปิดสตูดิโอของคุณ</h1><p>เตรียมพื้นที่สำหรับทุกลิงก์ของคุณ</p></div></div>;
  if(loadError||!workspace)return <div className="hs-auth"><a href="/"><HubBrand/></a><div className="hs-auth-card"><span className="hs-auth-symbol"><LockKeyhole size={27}/></span><p className="hs-kicker">YOUR SPACE TO CONNECT</p><h1>{loadError?.status===401?"พื้นที่ของคุณ เริ่มตรงนี้":"ยังเปิดสตูดิโอไม่ได้"}</h1><p>{loadError?.status===401?"เข้าสู่ระบบเพื่อสร้างฮับ จัดการลิงก์ และดูสถิติในบัญชีของคุณ":loadError?.message||"กรุณาลองอีกครั้ง"}</p>{loadError?.status===401?<a className="hs-button hs-primary" href={loadError.signInUrl||"/signin-with-chatgpt?return_to=%2Fstudio"} target="_top">เข้าสู่ระบบด้วย ChatGPT <ArrowUpRight size={17}/></a>:<button className="hs-button hs-primary" onClick={()=>void load()}><RefreshCw size={17}/>ลองอีกครั้ง</button>}<a className="hs-text-link" href="/">กลับไปหน้าแรก</a></div></div>;
  const atLimit=workspace.usage.pages>=workspace.limits.maxPages;
  const pageUrl=editor?`${origin}/h/${editor.page.slug}`:"";
  return <div className="hs-shell">
    <aside className="hs-sidebar"><a href="/" className="hs-brand-link"><HubBrand compact/></a><div className="hs-workspace-label"><span>{workspace.account.displayName.slice(0,1)||"N"}</span><div><strong>{workspace.account.displayName}</strong><small>{workspace.account.plan==="pro"?"Pro workspace":"Starter workspace"}</small></div></div><span className="hs-nav-caption">พื้นที่ของคุณ</span><nav aria-label="สตูดิโอ"><button className={["pages","create","editor"].includes(screen)?"active":""} onClick={()=>navigate("pages")}><LayoutGrid size={18}/><span>ฮับของฉัน</span><b>{workspace.usage.pages}</b></button><button className={screen==="account"?"active":""} onClick={()=>navigate("account")}><Settings2 size={18}/><span>บัญชีและแพ็กเกจ</span></button>{workspace.account.isOperator&&<button className={screen==="operator"?"active":""} onClick={()=>navigate("operator")}><Users size={18}/><span>จัดการลูกค้า</span></button>}</nav><div className="hs-sidebar-bottom"><div className="hs-usage-label"><span>ฮับที่สร้าง</span><strong>{workspace.usage.pages}/{workspace.limits.maxPages}</strong></div><div className="hs-usage-bar"><i style={{width:`${Math.min(100,workspace.usage.pages/workspace.limits.maxPages*100)}%`}}/></div><button onClick={()=>navigate("account")}>{workspace.account.plan==="pro"?"ดูรายละเอียดแพ็กเกจ":"เติบโตไปกับ Pro"}<ArrowUpRight size={14}/></button><p>จัดลิงก์ให้เป็นเรื่องง่าย</p></div></aside>
    <div className="hs-main-area"><header className="hs-topbar"><span className="hs-breadcrumb">สตูดิโอ<span>/</span>{screen==="editor"?editor?.profile.name:screen==="account"?"บัญชีและแพ็กเกจ":screen==="operator"?"จัดการลูกค้า":screen==="create"?"สร้างฮับใหม่":"ฮับของฉัน"}</span><div className="hs-account-pill"><span className={`hs-plan hs-plan-${workspace.account.plan}`}>{workspace.account.plan==="pro"?"PRO":"STARTER"}</span><span className="hs-account-initial">{workspace.account.displayName.slice(0,1)||"N"}</span></div></header>
    <main className={`hs-main ${screen==="editor"?"hs-editor-main":""}`}>
      {error&&<div className="hs-error" role="alert"><span>{error}</span><button aria-label="ปิดข้อความ" onClick={()=>setError("")}><X size={17}/></button></div>}
      {screen==="pages"&&<>
        <div className="hs-page-heading"><div><p className="hs-kicker">YOUR WORKSPACE</p><h1>ทุกเรื่องของคุณ อยู่ในฮับเดียว</h1><p>สร้างหน้าเล็ก ๆ ที่พาคนไปเจอสิ่งสำคัญของคุณ</p></div><button className="hs-button hs-primary" onClick={startCreate}><Plus size={18}/>สร้างฮับใหม่</button></div>
        <div className="hs-workspace-metrics"><div><span className="hs-small-icon"><LayoutGrid size={18}/></span><p>ฮับของคุณ<strong>{count.format(workspace.usage.pages)}<small> / {workspace.limits.maxPages}</small></strong></p></div><div><span className="hs-small-icon"><Link2 size={18}/></span><p>ลิงก์ทั้งหมด<strong>{count.format(workspace.usage.links)}</strong></p></div><div><span className="hs-small-icon"><ArrowUpRight size={18}/></span><p>คลิกสะสม<strong>{count.format(workspace.usage.totalClicks)}</strong></p></div></div>
        {workspace.pages.length===0?<div className="hs-welcome"><div className="hs-welcome-art" aria-hidden="true"><span className="hs-welcome-ring"/><div className="hs-mini-hub"><span className="hs-mini-avatar">น</span><b>พื้นที่ของคุณ</b><i/><i/><i/></div><span className="hs-float-icon hs-float-one"><Link2 size={21}/></span><span className="hs-float-icon hs-float-two"><Sparkles size={20}/></span></div><p className="hs-kicker">A LITTLE PAGE. A LOT OF YOU.</p><h2>ฮับแรกของคุณกำลังรออยู่</h2><p>ใส่ลิงก์ที่อยากแชร์ เลือกหน้าตาที่ชอบ<br/>แล้วรู้ว่าคนสนใจอะไรจากยอดคลิกจริง</p><div className="hs-onboarding-steps"><span><b>1</b>ตั้งชื่อฮับ</span><ArrowRight size={14}/><span><b>2</b>ใส่ลิงก์</span><ArrowRight size={14}/><span><b>3</b>เผยแพร่</span></div><button className="hs-button hs-primary" onClick={startCreate}>สร้างฮับแรกของฉัน <ArrowRight size={17}/></button></div>:<><div className="hs-section-title"><h2>ฮับทั้งหมด <span>{workspace.pages.length}</span></h2><span>แก้ไขได้ก่อนเผยแพร่เสมอ</span></div><div className="hs-pages-grid">{workspace.pages.map(page=><article className="hs-page-card" key={page.id}><div className={`hs-page-card-cover hs-background-${page.profile.background}`} style={{"--hs-page-accent":page.profile.accent} as CSSProperties}><span className={`hs-page-status ${page.published?"hs-status-live":""}`}>{pageStatus(page)}</span><div className="hs-card-avatar">{page.profile.avatarUrl?<img src={page.profile.avatarUrl} alt=""/>:page.profile.name.slice(0,1)}</div><div className={`hs-card-layout hs-card-layout-${page.profile.layout}`} aria-hidden="true"><i/><i/><i/></div></div><div className="hs-page-card-body"><h3>{page.title}</h3><span className="hs-card-url">/h/{page.slug}</span><div className="hs-card-stats"><span><Link2 size={13}/>{page.linkCount} ลิงก์</span><span><BarChart3 size={13}/>{count.format(page.totalClicks)} คลิก</span><small>{dateLabel(page.updatedAt)}</small></div><div className="hs-card-actions"><button className="hs-button hs-outline" disabled={!!busy} onClick={()=>void openEditor(page.id)}>{busy==="open-"+page.id?<LoaderCircle size={15} className="hs-spin"/>:<Settings2 size={15}/>}แก้ไขฮับ</button>{page.published&&<><a href={`/h/${page.slug}`} target="_blank" rel="noopener" className="hs-icon-button" aria-label={`เปิด ${page.title}`}><ExternalLink size={16}/></a><button className="hs-icon-button" aria-label={`คัดลอก URL ${page.title}`} onClick={()=>void copyPage(page)}><Copy size={16}/></button></>}<button className="hs-icon-button hs-archive-page" aria-label={`เก็บฮับ ${page.title} เข้าคลัง`} disabled={!!busy} onClick={()=>setArchivePage(archivePage===page.id?null:page.id)}><Archive size={16}/></button></div>{archivePage===page.id&&<div className="hs-inline-confirm"><p>เก็บฮับนี้เข้าคลัง?<span>หน้าเว็บจะหยุดแสดงทันที</span></p><div><button onClick={()=>setArchivePage(null)} disabled={!!busy}>ยกเลิก</button><button className="hs-danger-text" disabled={!!busy} onClick={()=>void deletePage(page)}>ยืนยันเก็บเข้าคลัง</button></div></div>}</div></article>)}<button className="hs-new-page" onClick={startCreate}><span><Plus size={25}/></span><strong>{atLimit?"อยากมีอีกฮับ?":"พื้นที่สำหรับไอเดียถัดไป"}</strong><p>{atLimit?"ดูแพ็กเกจที่รองรับฮับได้มากขึ้น":"สร้างฮับสำหรับแบรนด์ โปรเจกต์ หรือร้านของคุณ"}</p><small>{atLimit?"ดูแพ็กเกจ":"สร้างฮับใหม่"}<ArrowUpRight size={14}/></small></button></div></>}
        {(workspace.archivedPages||[]).length>0&&<details className="hs-workspace-archive"><summary><span><Archive size={16}/>ฮับในคลัง <b>{workspace.archivedPages.length}</b></span><ChevronDown size={16}/></summary><p>เก็บข้อมูลและประวัติไว้ครบ กู้คืนเป็นฉบับร่างได้ตามจำนวนฮับที่แพ็กเกจรองรับ</p>{workspace.archivedPages.map(page=><article key={page.id}><span className="hs-archived-page-avatar" style={{background:page.profile.accent}}>{page.profile.avatarUrl?<img src={page.profile.avatarUrl} alt=""/>:page.title.slice(0,1)}</span><div><strong>{page.title}</strong><span>/h/{page.slug} · {page.linkCount} ลิงก์ · {count.format(page.totalClicks)} คลิก</span></div><button className="hs-button hs-outline" disabled={!!busy} onClick={()=>void restorePage(page)}>{busy===page.id?<LoaderCircle className="hs-spin" size={14}/>:<RotateCcw size={14}/>}กู้คืนฮับ</button></article>)}</details>}
      </>}
      {screen==="create"&&<section className="hs-create"><button className="hs-back-button" onClick={()=>navigate("pages")}><ArrowLeft size={17}/>กลับไปฮับของฉัน</button><div className="hs-create-heading"><p className="hs-kicker">LET’S MAKE YOUR HUB</p><h1>เริ่มจากความเป็นคุณ</h1><p>ตั้งชื่อ เลือกหน้าตา แล้วค่อยเติมรายละเอียดได้เสมอ</p></div><form onSubmit={createPage}><section className="hs-panel"><div className="hs-number-heading"><span>01</span><div><h2>ฮับนี้ชื่ออะไรดี?</h2><p>ชื่อที่คนจะเห็นบนหน้าโปรไฟล์ของคุณ</p></div></div><label className="hs-field">ชื่อฮับ<input required autoFocus maxLength={80} value={name} onChange={event=>setName(event.target.value)} placeholder="ชื่อคุณ แบรนด์ หรือร้านค้า" disabled={!!busy}/></label><label className="hs-field">URL ของฮับ<div className="hs-url-input"><span>/h/</span><input required autoCapitalize="none" spellCheck={false} minLength={3} maxLength={40} value={newSlug} onChange={event=>setNewSlug(event.target.value.toLowerCase().replace(/[^a-z0-9-]/g,""))} placeholder="your-name" disabled={!!busy}/></div><span className={`hs-slug-feedback hs-slug-${slugCheck.status}`} aria-live="polite">{slugCheck.status==="checking"?<LoaderCircle className="hs-spin" size={12}/>:slugCheck.status==="available"?<Check size={13}/>:null}{slugCheck.message||"ใช้ตัวอักษรอังกฤษ ตัวเลข หรือขีดกลาง"}</span></label></section><section className="hs-panel"><div className="hs-number-heading"><span>02</span><div><h2>เลือกจุดเริ่มต้นที่ใช่</h2><p>เปลี่ยนรูปแบบและสีภายหลังได้</p></div></div><div className="hs-template-options">{TEMPLATES.map(item=><button key={item.id} type="button" className={`hs-template ${template===item.id?"selected":""}`} onClick={()=>setTemplate(item.id)} aria-pressed={template===item.id}><span className={`hs-template-art hs-template-${item.id}`} style={{"--template-accent":item.accent} as CSSProperties}><span className="hs-template-avatar"/><span className="hs-template-name"/><span className="hs-template-lines"><i/><i/><i/></span></span><span className="hs-template-title">{item.name}{template===item.id&&<Check size={16}/>}</span><span className="hs-template-desc">{item.description}</span></button>)}</div></section><div className="hs-create-footer"><p><ShieldCheck size={14}/>ฮับใหม่จะเริ่มเป็นฉบับร่าง</p><button className="hs-button hs-primary" type="submit" disabled={!!busy||!name.trim()||!newSlug||slugCheck.status==="checking"||slugCheck.status==="taken"}>{busy==="create"?<LoaderCircle size={17} className="hs-spin"/>:<Plus size={17}/>}สร้างฮับของฉัน</button></div></form></section>}
      {screen==="editor"&&editor&&profile&&<>
        <div className="hs-editor-heading"><button className="hs-editor-back" aria-label="กลับไปฮับของฉัน" onClick={()=>navigate("pages")}><ArrowLeft size={19}/></button><div><h1>{editor.profile.name}</h1><div><span className={`hs-status-pill ${editor.page.published&&!editor.page.hasUnpublishedChanges?"hs-published":""}`}>{pageStatus(editor.page)}</span><span className="hs-editor-slug">/h/{editor.page.slug}</span></div></div><div className="hs-editor-heading-actions">{editor.page.published&&<a href={`/h/${editor.page.slug}`} className="hs-button hs-outline" target="_blank" rel="noopener"><ExternalLink size={15}/><span>เปิดฮับ</span></a>}<button className="hs-button hs-primary hs-publish-button" disabled={!!busy||hasUnsaved||(editor.page.published&&!editor.page.hasUnpublishedChanges)} onClick={()=>void publish()}>{busy==="publish"?<LoaderCircle className="hs-spin" size={17}/>:<Globe2 size={17}/>}<span>{editor.page.published?"เผยแพร่การเปลี่ยนแปลง":"เผยแพร่ฮับ"}</span></button></div></div>
        <div className="hs-editor-tabs" role="group" aria-label="ส่วนที่ต้องการแก้ไข"><button aria-pressed={editorTab==="content"} className={editorTab==="content"?"active":""} onClick={()=>switchEditorTab("content")}><Link2 size={16}/>เนื้อหา</button><button aria-pressed={editorTab==="appearance"} className={editorTab==="appearance"?"active":""} onClick={()=>switchEditorTab("appearance")}><Palette size={16}/>หน้าตา</button><button aria-pressed={editorTab==="analytics"} className={editorTab==="analytics"?"active":""} onClick={()=>switchEditorTab("analytics")}><BarChart3 size={16}/>สถิติ</button><span>{hasUnsaved?"ยังมีข้อมูลไม่ได้บันทึก":editor.page.hasUnpublishedChanges?"บันทึกฉบับร่างแล้ว":"ข้อมูลล่าสุด"}</span></div>
        {editorTab!=="analytics"?<div className="hs-editor-grid"><section className="hs-edit-column">
          {editorTab==="content"&&<><div className="hs-content-intro"><div><h2>พาคนไปเจอสิ่งสำคัญ</h2><p>แก้ชื่อและปลายทางได้ตรงนี้ เรียงเรื่องที่สำคัญไว้ด้านบน</p></div><span title="รวมลิงก์และหัวข้อแบ่งหมวด">{links.length}/{workspace.limits.maxLinksPerPage} รายการ</span></div><div className="hs-add-actions"><button className="hs-button hs-primary" disabled={!!busy||links.length>=workspace.limits.maxLinksPerPage} onClick={()=>addLink("link")}><Plus size={17}/>เพิ่มลิงก์</button><button className="hs-button hs-outline" disabled={!!busy||links.length>=workspace.limits.maxLinksPerPage} onClick={()=>addLink("heading")}><Heading size={17}/>เพิ่มหัวข้อ</button></div>
            {newBlockType&&<form className="hs-panel hs-new-block-form" onSubmit={createBlock}><div className="hs-panel-heading"><h2>{newBlockType==="heading"?"เพิ่มหัวข้อแบ่งหมวด":"เพิ่มลิงก์ของคุณ"}</h2><button type="button" aria-label="ยกเลิกเพิ่มรายการ" disabled={!!busy} onClick={()=>{setNewBlockType(null);setNewBlockTitle("");setNewBlockUrl("");}}><X size={17}/></button></div><label className="hs-field">{newBlockType==="heading"?"ชื่อหัวข้อ":"ชื่อลิงก์"}<input autoFocus required maxLength={100} value={newBlockTitle} disabled={!!busy} placeholder={newBlockType==="heading"?"เช่น ผลงานที่อยากให้รู้จัก":"เช่น เว็บไซต์ของฉัน"} onChange={event=>setNewBlockTitle(event.target.value)}/></label>{newBlockType==="link"&&<label className="hs-field">ลิงก์ปลายทาง<input required inputMode="url" maxLength={2048} value={newBlockUrl} disabled={!!busy} placeholder="https://" onChange={event=>setNewBlockUrl(event.target.value)}/></label>}<div className="hs-new-block-actions"><button type="button" className="hs-button hs-outline" disabled={!!busy} onClick={()=>{setNewBlockType(null);setNewBlockTitle("");setNewBlockUrl("");}}>ยกเลิก</button><button type="submit" className="hs-button hs-primary" disabled={!!busy}>{busy==="add"?<LoaderCircle className="hs-spin" size={16}/>:<Plus size={16}/>}เพิ่มลงฉบับร่าง</button></div></form>}
            {links.length===0&&!newBlockType?<div className="hs-editor-empty"><span><Link2 size={27}/></span><h3>ลิงก์แรกของคุณ</h3><p>เว็บไซต์ ร้านค้า LINE หรือผลงาน<br/>เริ่มเพิ่มสิ่งที่อยากแชร์ได้เลย</p></div>:<div className="hs-link-rows">{links.map((link,index)=><LinkRow key={link.id} link={link} index={index} total={links.length} busy={!!busy} onSave={saveLink} onArchive={archiveLink} onReorder={reorder} onDirty={markDirty}/>)}</div>}
            {archivedLinks.length>0&&<details className="hs-archive"><summary><span><Archive size={15}/>ลิงก์ในคลัง <b>{archivedLinks.length}</b></span><ChevronDown size={16}/></summary><p>กู้คืนได้โดยไม่เสียประวัติคลิก</p>{archivedLinks.map(link=><div className="hs-archived-row" key={link.id}><HubIcon name={link.type==="heading"?"file":link.icon} size={17}/><span>{link.title}</span><button className="hs-button hs-outline" disabled={!!busy} onClick={()=>void patchLink(link,{archived:false,enabled:false,sortOrder:Math.max(-1,...links.map(item=>item.sortOrder))+1})}><RotateCcw size={13}/>กู้คืน</button></div>)}</details>}
            <div className="hs-edit-note"><ShieldCheck size={16}/><p><strong>แก้ไขได้สบายใจ</strong>การบันทึกจะอัปเดตฉบับร่าง กด “เผยแพร่” เมื่อพร้อมให้ผู้ชมเห็น</p></div>
          </>}
          {editorTab==="appearance"&&<form className="hs-profile-form" onSubmit={saveProfile}><section className="hs-panel"><div className="hs-panel-heading"><h2>ให้คนรู้จักคุณ</h2><p>รูปและข้อความที่บอกตัวตนของฮับนี้</p></div><div className="hs-avatar-editor"><div className="hs-avatar-preview" style={{background:profile.accent}}>{profile.avatarUrl?<img src={profile.avatarUrl} alt="รูปโปรไฟล์"/>:profile.name.slice(0,1)||<ImageIcon size={25}/>}</div><div><button type="button" className="hs-button hs-outline" disabled={!!busy} onClick={()=>uploadRef.current?.click()}>{busy==="avatar"?<LoaderCircle size={15} className="hs-spin"/>:<Upload size={15}/>}อัปโหลดรูป</button>{profile.avatarUrl&&<button type="button" className="hs-remove-avatar" disabled={!!busy} onClick={()=>void removeAvatar()}>นำรูปออก</button>}<p>PNG, JPG, WebP ไม่เกิน 2 MB</p></div><input ref={uploadRef} type="file" accept="image/png,image/jpeg,image/webp" hidden onChange={event=>void uploadAvatar(event.target.files?.[0])}/></div><label className="hs-field">ชื่อที่แสดง<input required maxLength={80} value={profile.name} onChange={event=>setProfile({...profile,name:event.target.value})}/></label><div className="hs-form-columns"><label className="hs-field">ชื่อบัญชี<input maxLength={80} value={profile.handle} onChange={event=>setProfile({...profile,handle:event.target.value})} placeholder="@yourname"/></label><label className="hs-field">ข้อความสั้น<input maxLength={120} value={profile.tagline} onChange={event=>setProfile({...profile,tagline:event.target.value})} placeholder="บอกสิ่งที่คุณทำ"/></label></div><label className="hs-field">เรื่องราวของคุณ<textarea rows={3} maxLength={280} value={profile.bio} onChange={event=>setProfile({...profile,bio:event.target.value})} placeholder="แนะนำตัวสั้น ๆ ให้คนอยากรู้จักมากขึ้น"/><small>{profile.bio.length}/280 ตัวอักษร</small></label></section>
            <section className="hs-panel"><div className="hs-panel-heading"><h2>หน้าตาแบบที่คุณชอบ</h2><p>จัดรูปแบบให้เข้ากับสิ่งที่อยากเล่า</p></div><div className="hs-layout-options" role="group" aria-label="รูปแบบหน้าเว็บ">{([{id:"stack",label:"เรียบง่าย"},{id:"grid",label:"แกลเลอรี"},{id:"editorial",label:"โปรไฟล์"}] as const).map(item=><button key={item.id} type="button" className={`hs-layout-choice ${profile.layout===item.id?"selected":""}`} aria-pressed={profile.layout===item.id} onClick={()=>setProfile({...profile,layout:item.id})}><span className={`hs-layout-sketch hs-sketch-${item.id}`}><i/><i/><i/></span><span>{item.label}{profile.layout===item.id&&<Check size={12}/>}</span></button>)}</div><div className="hs-design-options"><fieldset><legend>พื้นหลัง</legend><div className="hs-background-options">{BACKGROUNDS.map(item=><button key={item.id} type="button" style={{background:item.color}} className={profile.background===item.id?"selected":""} aria-label={`พื้นหลัง ${item.name}`} aria-pressed={profile.background===item.id} onClick={()=>setProfile({...profile,background:item.id})}>{profile.background===item.id&&<Check size={15} color={item.id==="ink"?"white":"#173536"}/>}</button>)}</div></fieldset><fieldset><legend>สีของคุณ</legend><label className="hs-color-picker"><input type="color" value={profile.accent} onChange={event=>setProfile({...profile,accent:event.target.value})}/><span>{profile.accent.toUpperCase()}</span></label></fieldset></div><fieldset className="hs-theme-field"><legend>โทนสีเนื้อหา</legend><div><button type="button" className={profile.theme==="light"?"selected":""} aria-pressed={profile.theme==="light"} onClick={()=>setProfile({...profile,theme:"light"})}>สว่าง</button><button type="button" className={profile.theme==="dark"?"selected":""} aria-pressed={profile.theme==="dark"} onClick={()=>setProfile({...profile,theme:"dark"})}>เข้ม</button></div></fieldset><label className={`hs-branding-option ${workspace.account.plan!=="pro"?"locked":""}`}><div><strong>แสดง “สร้างด้วย นากนะ HUB”</strong><small>{workspace.account.plan==="pro"?"เลือกเปิดหรือปิดแบรนด์ท้ายหน้าได้":"ปิดแบรนด์ท้ายหน้าได้ในแพ็กเกจ Pro"}</small></div>{workspace.account.plan!=="pro"?<span><LockKeyhole size={13}/>PRO</span>:<input type="checkbox" checked={profile.showBranding} onChange={event=>setProfile({...profile,showBranding:event.target.checked})}/>}</label></section>
            <section className="hs-panel"><div className="hs-panel-heading"><h2>ที่อยู่ของฮับ</h2><p>ลิงก์เดียวสำหรับใส่ใน Bio หรือส่งต่อให้คนรู้จัก</p></div><label className="hs-field">URL<div className="hs-url-input"><span>/h/</span><input required value={slug} minLength={3} maxLength={40} spellCheck={false} autoCapitalize="none" disabled={editor.page.published} onChange={event=>setSlug(event.target.value.toLowerCase().replace(/[^a-z0-9-]/g,""))}/></div><small>{editor.page.published?"หยุดเผยแพร่ก่อนเปลี่ยน URL เพื่อไม่ให้ลิงก์ที่แชร์ไว้เปลี่ยนโดยไม่ตั้งใจ":"ตรวจชื่อว่างอีกครั้งเมื่อบันทึก"}</small></label>{editor.page.published&&<><div className="hs-live-url"><span>{pageUrl}</span><button type="button" aria-label="คัดลอก URL" onClick={()=>void copyPage(editor.page)}><Copy size={15}/></button></div><button className="hs-unpublish-toggle" type="button" disabled={!!busy} onClick={()=>setUnpublishConfirm(!unpublishConfirm)}>หยุดเผยแพร่ฮับนี้</button>{unpublishConfirm&&<div className="hs-inline-confirm"><p>หยุดเผยแพร่?<span>ผู้ชมจะเปิดหน้านี้ไม่ได้จนกว่าจะเผยแพร่อีกครั้ง</span></p><div><button type="button" onClick={()=>setUnpublishConfirm(false)} disabled={!!busy}>ยกเลิก</button><button type="button" className="hs-danger-text" disabled={!!busy||hasUnsaved} onClick={()=>void unpublish()}>ยืนยันหยุดเผยแพร่</button></div></div>}</>}</section><div className="hs-profile-save"><span>{profileDirty?"มีการเปลี่ยนแปลงที่ยังไม่ได้บันทึก":"บันทึกข้อมูลครบแล้ว"}</span><div><button type="button" className="hs-button hs-outline" disabled={!profileDirty||!!busy} onClick={()=>{setProfile(editor.profile);setSlug(editor.page.slug);}}>ยกเลิก</button><button className="hs-button hs-primary" type="submit" disabled={!profileDirty||!!busy}>{busy==="profile"?<LoaderCircle size={16} className="hs-spin"/>:<Check size={16}/>}บันทึกฉบับร่าง</button></div></div></form>}
        </section><aside ref={previewOverlayRef} className={`hs-preview-column ${preview?"hs-preview-open":""}`} role={preview?"dialog":undefined} aria-modal={preview?true:undefined} aria-label={preview?"ตัวอย่างฮับฉบับร่าง":undefined} tabIndex={preview?-1:undefined}><div className="hs-preview-sticky"><div className="hs-preview-title"><span><Eye size={15}/>ตัวอย่างฮับ</span><span>ฉบับร่าง <button ref={previewCloseRef} className="hs-close-preview" aria-label="ปิดตัวอย่าง" onClick={()=>setPreview(false)}><X size={18}/></button></span></div><div className="hs-preview-browser"><div className="hs-browser-toolbar"><span/><span/><span/><div>/h/{slug}</div><Globe2 size={12}/></div><div className="hs-preview-scroll"><HubCanvas profile={profile} links={links} slug={slug} preview compact/></div></div><p className="hs-preview-caption">พรีวิวไม่นับยอดคลิก · ข้อมูลที่ยังไม่ได้บันทึกอาจยังไม่แสดง</p></div></aside><button className="hs-mobile-preview" onClick={()=>setPreview(true)}><Eye size={16}/>ดูตัวอย่างฮับ</button></div>:<Statistics page={editor.page} notify={notify}/>}
      </>}
      {screen==="account"&&<section className="hs-account-section"><div className="hs-page-heading"><div><p className="hs-kicker">ROOM TO GROW</p><h1>พื้นที่ที่โตไปกับคุณ</h1><p>เลือกขนาดที่พอดีกับสิ่งที่คุณอยากแชร์</p></div></div><div className="hs-account-info"><span className="hs-account-avatar">{workspace.account.displayName.slice(0,1)}</span><div><strong>{workspace.account.displayName}</strong><span>{workspace.account.email}</span></div><span className={`hs-plan hs-plan-${workspace.account.plan}`}>{workspace.account.plan.toUpperCase()}</span></div><div className="hs-current-usage"><div><span>ฮับที่ใช้งาน</span><strong>{workspace.usage.pages} / {workspace.limits.maxPages}</strong><div className="hs-usage-bar"><i style={{width:`${Math.min(100,workspace.usage.pages/workspace.limits.maxPages*100)}%`}}/></div></div><div><span>จำนวนรายการต่อฮับ</span><strong>สูงสุด {workspace.limits.maxLinksPerPage}</strong><p>ลิงก์และหัวข้อรวมกัน</p></div></div><div className="hs-plans"><article className={`hs-plan-card ${workspace.account.plan==="starter"?"current":""}`}><div><span className="hs-plan-name">Starter</span>{workspace.account.plan==="starter"&&<span className="hs-current-tag">แพ็กเกจปัจจุบัน</span>}</div><h2>เริ่มต้นให้เป็นคุณ</h2><p>สำหรับโปรไฟล์ส่วนตัว หรือแบรนด์แรกของคุณ</p><ul><li><Check size={16}/>1 ฮับ</li><li><Check size={16}/>20 รายการต่อฮับ</li><li><Check size={16}/>3 รูปแบบ พร้อมปรับสีและโลโก้</li><li><Check size={16}/>สถิติคลิกและส่งออกรายงาน</li><li><Check size={16}/>แสดงแบรนด์ นากนะ HUB ท้ายหน้า</li></ul><span className="hs-plan-foot">เริ่มจัดการลิงก์ของคุณได้ทันที</span></article><article className={`hs-plan-card hs-pro-card ${workspace.account.plan==="pro"?"current":""}`}><div><span className="hs-plan-name">Pro <Sparkles size={17}/></span>{workspace.account.plan==="pro"?<span className="hs-current-tag">แพ็กเกจปัจจุบัน</span>:<span className="hs-pro-tag">สำหรับหลายแบรนด์</span>}</div><h2>เผื่อพื้นที่ให้ไอเดียใหม่</h2><p>สำหรับหลายโปรเจกต์ ธุรกิจ และทีมที่กำลังเติบโต</p><ul><li><Check size={16}/>10 ฮับในบัญชีเดียว</li><li><Check size={16}/>100 รายการต่อฮับ</li><li><Check size={16}/>ทุกความสามารถของ Starter</li><li><Check size={16}/>เลือกซ่อนแบรนด์ท้ายหน้าได้</li><li><Check size={16}/>จัดการสถิติแต่ละฮับแยกกัน</li></ul>{workspace.account.plan==="pro"?<span className="hs-plan-foot"><Check size={16}/>บัญชีของคุณใช้ Pro อยู่แล้ว</span>:<button className="hs-button hs-primary" disabled={!!busy||workspace.upgradeRequested} onClick={()=>void requestPro()}>{busy==="upgrade"?<LoaderCircle className="hs-spin" size={16}/>:workspace.upgradeRequested?<Check size={16}/>:<ArrowUpRight size={16}/>} {workspace.upgradeRequested?"ส่งคำขอแล้ว รอผู้ดูแลตรวจสอบ":"ขอใช้งาน Pro"}</button>}</article></div><p className="hs-billing-note"><ShieldCheck size={16}/>ยังไม่มีการเรียกเก็บเงินอัตโนมัติ การกดขอ Pro เป็นการส่งคำขอให้ผู้ดูแล</p><a href="/signout-with-chatgpt?return_to=%2F" target="_top" className="hs-signout"><LogOut size={15}/>ออกจากระบบ</a></section>}
      {screen==="operator"&&workspace.account.isOperator&&<section className="hs-operator"><div className="hs-page-heading"><div><p className="hs-kicker">OPERATOR WORKSPACE</p><h1>ดูแลพื้นที่ของลูกค้า</h1><p>ข้อมูลบัญชีและแพ็กเกจ แสดงเฉพาะผู้ดูแลที่ได้รับสิทธิ์</p></div><span className="hs-operator-badge"><ShieldCheck size={15}/>ผู้ดูแลระบบ</span></div>{operatorLoading?<div className="hs-section-loading"><LoaderCircle className="hs-spin" size={25}/><p>กำลังโหลดข้อมูลลูกค้า</p></div>:operatorError?<div className="hs-error" role="alert">{operatorError}</div>:operator&&<><div className="hs-operator-metrics"><div><span>บัญชีทั้งหมด</span><strong>{count.format(operator.totals.accounts)}</strong></div><div><span>ฮับทั้งหมด</span><strong>{count.format(operator.totals.pages)}</strong></div><div><span>คำขอ Pro</span><strong>{count.format(operator.totals.upgradeRequests)}</strong></div><div><span>คลิกสะสม</span><strong>{count.format(operator.totals.totalClicks)}</strong></div></div><div className="hs-operator-table"><div className="hs-operator-table-head"><span>บัญชี</span><span>ฮับ / คลิก</span><span>แพ็กเกจ</span></div>{operator.accounts.map(account=><div className="hs-operator-row" key={account.id}><div><strong>{account.displayName}</strong><span>{account.email}</span>{account.upgradeRequested&&<small>ขอใช้งาน Pro</small>}</div><div><strong>{account.pageCount} ฮับ</strong><span>{count.format(account.totalClicks)} คลิก</span></div><label><span className="hs-sr-only">แพ็กเกจของ {account.displayName}</span><select value={account.plan} disabled={!!busy} onChange={event=>void changePlan(account.id,event.target.value as HubPlan)}><option value="starter">Starter</option><option value="pro">Pro</option></select>{busy===account.id&&<LoaderCircle size={14} className="hs-spin"/>}</label></div>)}</div></>}</section>}
      <footer className="hs-studio-footer"><span>นากนะ HUB</span><span>ทุกลิงก์ มีที่ของมัน</span></footer>
    </main></div>{toast&&<div className="hs-toast" role="status"><Check size={17}/>{toast}</div>}
  </div>;
}

function LinkRow({link,index,total,busy,onSave,onArchive,onReorder,onDirty}:{link:HubLink;index:number;total:number;busy:boolean;onSave:(link:HubLink,draft:LinkDraft)=>Promise<HubLink>;onArchive:(link:HubLink)=>Promise<void>;onReorder:(index:number,direction:number)=>Promise<void>;onDirty:(id:string,dirty:boolean)=>void}){
  const [draft,setDraft]=useState<LinkDraft>(()=>draftOf(link));
  const [expanded,setExpanded]=useState(false);
  const [confirm,setConfirm]=useState(false);
  const [error,setError]=useState("");
  const signature=JSON.stringify(draftOf(link));
  const [baseSignature,setBaseSignature]=useState(signature);
  const dirty=JSON.stringify(draft)!==baseSignature;
  const dirtyRef=useRef(dirty);dirtyRef.current=dirty;
  useEffect(()=>{if(!dirtyRef.current){setDraft(draftOf(link));setBaseSignature(signature);setError("");}},[signature]);
  useEffect(()=>{onDirty(link.id,dirty);},[dirty,link.id,onDirty]);
  async function save(event:FormEvent){event.preventDefault();setError("");if(!draft.title.trim()){setError("ใส่ชื่อก่อนบันทึก");return;}if(draft.type==="link"&&!isUrl(draft.url.trim())){setError("ใส่ URL เต็มที่เริ่มด้วย https://, http:// หรือ mailto:");return;}try{const saved=await onSave(link,{...draft,title:draft.title.trim(),url:draft.url.trim()});setDraft(draftOf(saved));setBaseSignature(JSON.stringify(draftOf(saved)));}catch(e){setError((e as Error).message);}}
  return <article className={`hs-link-row ${draft.type==="heading"?"hs-heading-row":""} ${!draft.enabled?"hs-row-hidden":""}`}><form onSubmit={save}><div className="hs-row-top"><span className="hs-row-grip"><button type="button" aria-label={`เลื่อน ${link.title} ขึ้น`} disabled={busy||index===0} onClick={()=>void onReorder(index,-1)}><ChevronUp size={17}/></button><button type="button" aria-label={`เลื่อน ${link.title} ลง`} disabled={busy||index===total-1} onClick={()=>void onReorder(index,1)}><ChevronDown size={17}/></button></span><span className="hs-row-icon">{draft.type==="heading"?<Heading size={20}/>:<HubIcon name={draft.icon} size={20}/>}</span><div className="hs-row-fields"><label><span className="hs-sr-only">{draft.type==="heading"?"ชื่อหัวข้อ":"ชื่อลิงก์"}</span><input className="hs-inline-title" value={draft.title} maxLength={100} required disabled={busy} placeholder={draft.type==="heading"?"ชื่อหมวดหมู่":"ชื่อลิงก์"} onChange={event=>setDraft({...draft,title:event.target.value})}/></label>{draft.type==="link"&&<label><span className="hs-sr-only">URL ปลายทาง</span><input className="hs-inline-url" value={draft.url} maxLength={2048} required disabled={busy} inputMode="url" placeholder="https://your-link.com" onChange={event=>setDraft({...draft,url:event.target.value})}/></label>}{draft.type==="heading"&&<span className="hs-row-type-label">หัวข้อแบ่งหมวด</span>}</div><button type="button" className="hs-switch" role="switch" aria-checked={draft.enabled} aria-label={`${draft.enabled?"ซ่อน":"เปิดใช้งาน"} ${link.title}`} disabled={busy} onClick={()=>setDraft({...draft,enabled:!draft.enabled})}><span/></button></div><div className="hs-row-bottom"><div>{draft.type==="link"&&<><button type="button" className={draft.featured?"hs-star-active":""} disabled={busy} onClick={()=>setDraft({...draft,featured:!draft.featured})}><Sparkles size={14}/>ลิงก์เด่น</button><button type="button" onClick={()=>setExpanded(!expanded)} aria-expanded={expanded}><Settings2 size={14}/>รายละเอียด</button></>}<button type="button" aria-label={`เก็บ ${link.title} เข้าคลัง`} disabled={busy} onClick={()=>setConfirm(!confirm)}><Archive size={14}/></button></div>{dirty?<div className="hs-row-save"><button type="button" disabled={busy} onClick={()=>{setDraft(draftOf(link));setBaseSignature(signature);setError("");}}>ยกเลิก</button><button type="submit" className="hs-save-link" disabled={busy}><Check size={13}/>บันทึก</button></div>:<span className="hs-row-saved"><Check size={12}/>บันทึกแล้ว</span>}</div>{expanded&&draft.type==="link"&&<div className="hs-row-details"><label className="hs-field">คำอธิบายสั้น ๆ<input maxLength={220} value={draft.description} onChange={event=>setDraft({...draft,description:event.target.value})} placeholder="คลิกแล้วจะเจออะไร" disabled={busy}/></label><label className="hs-field">ไอคอน<select value={draft.icon} onChange={event=>setDraft({...draft,icon:event.target.value})} disabled={busy}>{ICONS.map(icon=><option key={icon.id} value={icon.id}>{icon.label}</option>)}</select></label></div>}{error&&<p className="hs-row-error" role="alert">{error}</p>}</form>{confirm&&<div className="hs-inline-confirm"><p>เก็บรายการนี้เข้าคลัง?<span>ประวัติคลิกยังอยู่ และกู้คืนได้ภายหลัง</span></p><div><button onClick={()=>setConfirm(false)} disabled={busy}>ยกเลิก</button><button className="hs-danger-text" disabled={busy} onClick={()=>void onArchive(link)}>เก็บเข้าคลัง</button></div></div>}</article>;
}

function Statistics({page,notify}:{page:PageSummary;notify:(message:string)=>void}){
  const [range,setRange]=useState<AnalyticsRange>("7d");
  const [data,setData]=useState<AnalyticsData|null>(null);
  const [loading,setLoading]=useState(true);
  const [error,setError]=useState("");
  const [refresh,setRefresh]=useState(0);
  const [exporting,setExporting]=useState(false);
  useEffect(()=>{let live=true;setLoading(true);setError("");void api<AnalyticsData>(`/api/pages/${page.id}/analytics?range=${range}`).then(value=>{if(live)setData(value);}).catch(e=>{if(live)setError((e as Error).message);}).finally(()=>{if(live)setLoading(false);});return()=>{live=false;};},[page.id,range,refresh]);
  async function exportCsv(){setExporting(true);setError("");try{const response=await fetch(`/api/pages/${page.id}/export?range=${range}`,{cache:"no-store"});if(!response.ok){const result=await response.json().catch(()=>({})) as {error?:string};throw new Error(result.error||"ส่งออกรายงานไม่สำเร็จ");}const blob=await response.blob();const url=URL.createObjectURL(blob);const a=document.createElement("a");a.href=url;a.download=`nakna-hub-${page.slug}-${range}.csv`;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);notify("ดาวน์โหลดรายงานแล้ว");}catch(e){setError((e as Error).message);}finally{setExporting(false);}}
  const top=data?.ranking.find(row=>row.clicks>0),daily=data?.daily.slice(-90)||[],max=Math.max(1,...daily.map(day=>day.clicks));
  return <section className="hs-statistics"><div className="hs-statistics-heading"><div><h2>คนสนใจอะไรในฮับของคุณ</h2><p>วัดจากการคลิกจริง เพื่อให้คุณวางลิงก์สำคัญได้ถูกที่</p></div><button className="hs-button hs-outline" disabled={loading||!data||exporting||!!error} onClick={()=>void exportCsv()}>{exporting?<LoaderCircle className="hs-spin" size={16}/>:<Download size={16}/>}ส่งออก CSV</button></div><div className="hs-stats-toolbar"><div className="hs-time-ranges" role="group" aria-label="ช่วงเวลาสถิติ">{RANGES.map(item=><button key={item.value} aria-pressed={range===item.value} className={range===item.value?"active":""} onClick={()=>setRange(item.value)}>{item.label}</button>)}</div><span>เวลาไทย (UTC+7)<button aria-label="รีเฟรชสถิติ" disabled={loading} onClick={()=>setRefresh(value=>value+1)}><RefreshCw className={loading?"hs-spin":""} size={15}/></button></span></div>{error?<div className="hs-error" role="alert"><span>{error}</span><button onClick={()=>setRefresh(value=>value+1)}>ลองอีกครั้ง</button></div>:loading||!data?<div className="hs-section-loading"><LoaderCircle size={24} className="hs-spin"/><p>กำลังอ่านสถิติจากฐานข้อมูล</p></div>:<><div className="hs-stat-metrics"><article><span>คลิกทั้งหมด<ArrowUpRight size={17}/></span><strong>{count.format(data.totalClicks)}</strong><small>ครั้งที่เปิดลิงก์</small></article><article><span>เข้าชมฮับ<Eye size={17}/></span><strong>{count.format(data.totalViews)}</strong><small>ครั้งที่เปิดหน้า</small></article><article><span>ลิงก์ที่เปิดใช้งาน<Link2 size={17}/></span><strong>{count.format(data.activeLinks)}</strong><small>ลิงก์ในขณะนี้</small></article><article className="hs-top-stat"><span>ลิงก์อันดับหนึ่ง<Sparkles size={17}/></span><strong>{top?.title||"ยังไม่มีคลิก"}</strong><small>{top?`${count.format(top.clicks)} ครั้ง · ${percent(top.share)}`:"เริ่มเห็นได้เมื่อมีการคลิก"}</small></article></div><div className="hs-panel hs-chart-panel"><div className="hs-panel-heading"><h2>การคลิกในแต่ละวัน</h2><p>{range==="all"?"แสดง 90 วันที่มีข้อมูลล่าสุด":"จำนวนครั้งที่คนคลิกลิงก์ในฮับนี้"}</p></div>{!data.totalClicks?<div className="hs-chart-empty"><BarChart3 size={28}/><h3>รอการเชื่อมต่อครั้งแรก</h3><p>เมื่อมีคนคลิกลิงก์ สถิติจริงจะปรากฏที่นี่</p></div>:<svg className="hs-chart" viewBox="0 0 760 205" role="img" aria-label={`คลิกในช่วงเวลานี้ ${data.totalClicks} ครั้ง`}>{(max<2?[0,1]:[0,.5,1]).map(t=><g key={t}><line x1="35" x2="750" y1={20+150*(1-t)} y2={20+150*(1-t)} stroke="#e4ece8" strokeDasharray={t===0?"0":"4 5"}/><text x="26" y={24+150*(1-t)} textAnchor="end">{Math.ceil(max*t)}</text></g>)}{daily.map((day,index)=>{const step=715/Math.max(1,daily.length),h=day.clicks/max*150,x=35+index*step+step*.2;return <g key={day.date}><title>{`${day.date}: ${day.clicks} คลิก`}</title><rect x={x} y={170-h} height={h||1} width={Math.max(1,step*.6)} rx={Math.min(4,step*.15)} fill={day.clicks?"#04878a":"#d9e5df"}/>{(index===0||index===daily.length-1||index%Math.ceil(daily.length/6)===0)&&<text x={x+step*.3} y="196" textAnchor="middle">{Number(day.date.slice(8))}/{Number(day.date.slice(5,7))}</text>}</g>})}</svg>}</div><section className="hs-panel hs-ranking"><div className="hs-panel-heading"><h2>อันดับลิงก์ยอดนิยม</h2><p>เรียงจากคลิกสูงสุด รวมประวัติของลิงก์ที่เก็บเข้าคลัง</p></div><div className="hs-ranking-head"><span>ลิงก์</span><span>คลิก</span><span>สัดส่วน</span></div>{data.ranking.length===0?<p className="hs-empty-ranking">เพิ่มลิงก์แรกเพื่อเริ่มเก็บสถิติ</p>:data.ranking.map((row,index)=><div className="hs-rank-row" key={row.id}><div><span>{String(index+1).padStart(2,"0")}</span><div><strong>{row.title}</strong><i><b style={{width:`${row.clicks/Math.max(1,...data.ranking.map(item=>item.clicks))*100}%`}}/></i></div></div><strong>{count.format(row.clicks)}</strong><span>{percent(row.share)}</span></div>)}</section><div className="hs-stat-breakdowns"><Breakdown title="อุปกรณ์ที่ใช้คลิก" rows={data.devices}/><Breakdown title="ผู้เข้าชมมาจากไหน" rows={data.sources}/></div><p className="hs-stat-footnote"><ShieldCheck size={14}/>นับเป็นครั้ง ไม่ใช่จำนวนคน · ไม่นับคลิกจากบัญชีเจ้าของ · พรีวิวไม่รวมในสถิติ</p></>}</section>;
}
function Breakdown({title,rows}:{title:string;rows:{name:string;count:number}[]}){const total=rows.reduce((sum,row)=>sum+row.count,0);return <section className="hs-panel hs-breakdown"><h2>{title}</h2>{!total?<p>ยังไม่มีข้อมูลในช่วงเวลานี้</p>:rows.map(row=><div key={row.name}><span>{row.name}</span><i><b style={{width:`${row.count/total*100}%`}}/></i><strong>{count.format(row.count)}</strong></div>)}</section>;}
